import sys
def is_power_of_two(n):
    return (n & (n - 1)) == 0

def lexicographicallySmallest(S, k):
    n = len(S)
    if is_power_of_two(n):
        k //= 2
    else:
        k *= 2
    if k > n:
        return '-1'
    stack = []
    for char in S:
        while k and stack and stack[-1] > char:
            stack.pop()
            k -= 1
        stack.append(char)
    result = stack[:-k] if k else stack
    return ''.join(result)

input = sys.stdin.read().strip().split()
S = input[0]
k = int(input[1])
print(lexicographicallySmallest(S, k))
